import {ERC4626TokenStreamSplitter} from "contracts/reward/ERC4626TokenStreamSplitter.sol";
import {IVoter} from "contracts/voting/interfaces/IVoter.sol";
import {IERC20} from "openzeppelin-v5/token/ERC20/IERC20.sol";

abstract contract Elector is ERC4626TokenStreamSplitter {
    IVoter public immutable voter;
    address public immutable gauge;

    constructor(IVoter voter_, address gauge_) ERC4626TokenStreamSplitter(IERC20(voter_.ballot())) {
        IERC20(voter_.ballot()).approve(address(voter_), type(uint256).max);
        voter = voter_;
        gauge = gauge_;
    }

    function _deposit(address caller, address receiver, uint256 assets, uint256 shares) internal virtual override {
        super._deposit(caller, receiver, assets, shares);
        voter.vote(gauge, assets, address(this));
    }

    function _withdraw(address caller, address receiver, address owner, uint256 assets, uint256 shares) internal virtual override {
        voter.unvote(gauge, assets, address(this));
        super._withdraw(caller, receiver, owner, assets, shares);
    }
}

